import urllib.parse


class UrlPath:
    ENCODING_DEFAULT = None  # Placeholder, not a magic number but a symbolic constant for clarity if needed

    def __init__(self):
        self._segments = []
        self._with_end_tag = False

    @property
    def segments(self):
        return self._segments[:]  # Return a copy to encapsulate the collection

    @property
    def with_end_tag(self):
        return self._with_end_tag

    def add(self, segment):
        self._segments.append(self.fix_path(segment))

    def parse(self, path, charset):
        if path:
            self._set_end_tag_if_needed(path)
            self._parse_path_elements(path, charset)

    def _set_end_tag_if_needed(self, path):
        if path.endswith('/'):
            self._with_end_tag = True

    def _parse_path_elements(self, path, charset):
        fixed_path = self.fix_path(path)
        if fixed_path:
            self._add_decoded_segments(fixed_path, charset)

    def _add_decoded_segments(self, path, charset):
        for seg in path.split('/'):
            decoded_seg = urllib.parse.unquote(seg, encoding=charset)
            self._segments.append(decoded_seg)

    @staticmethod
    def fix_path(path):
        if not path:
            return ''
        return path.strip('/')
